pub struct Query<'a> {
    pub _tab: flatbuffers::Table<'a>,
}

impl<'a> flatbuffers::Follow<'a> for Query<'a> {
    type Inner = Query<'a>;
    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self {
            _tab: flatbuffers::Table::new(buf, loc),
        }
    }
}

impl<'a> Query<'a> {
    pub const VT_QUERY: flatbuffers::VOffsetT = 4;
    pub const VT_VALUES: flatbuffers::VOffsetT = 6;
    pub const VT_LIMIT: flatbuffers::VOffsetT = 8;
    pub const VT_BOUND_SOURCES: flatbuffers::VOffsetT = 10;
    pub const VT_EXPLAIN: flatbuffers::VOffsetT = 12;

    #[inline]
    pub unsafe fn init_from_table(table: flatbuffers::Table<'a>) -> Self {
        Query { _tab: table }
    }
    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args QueryArgs<'args>,
    ) -> flatbuffers::WIPOffset<Query<'bldr>> {
        let mut builder = QueryBuilder::new(_fbb);
        if let Some(x) = args.explain {
            builder.add_explain(x);
        }
        if let Some(x) = args.bound_sources {
            builder.add_bound_sources(x);
        }
        builder.add_limit(args.limit);
        if let Some(x) = args.values {
            builder.add_values(x);
        }
        if let Some(x) = args.query {
            builder.add_query(x);
        }
        builder.finish()
    }

    #[inline]
    pub fn query(&self) -> QueryElement<'a> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe {
            self._tab
                .get::<flatbuffers::ForwardsUOffset<QueryElement>>(Query::VT_QUERY, None)
                .unwrap()
        }
    }
    #[inline]
    pub fn values(
        &self,
    ) -> Option<flatbuffers::Vector<'a, flatbuffers::ForwardsUOffset<ValueInstance<'a>>>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe {
            self._tab.get::<flatbuffers::ForwardsUOffset<
                flatbuffers::Vector<'a, flatbuffers::ForwardsUOffset<ValueInstance>>,
            >>(Query::VT_VALUES, None)
        }
    }
    #[inline]
    pub fn limit(&self) -> u32 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<u32>(Query::VT_LIMIT, Some(0)).unwrap() }
    }
    #[inline]
    pub fn bound_sources(
        &self,
    ) -> Option<flatbuffers::Vector<'a, flatbuffers::ForwardsUOffset<TableSourceInstance<'a>>>>
    {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe {
            self._tab.get::<flatbuffers::ForwardsUOffset<
                flatbuffers::Vector<'a, flatbuffers::ForwardsUOffset<TableSourceInstance>>,
            >>(Query::VT_BOUND_SOURCES, None)
        }
    }
    #[inline]
    pub fn explain(&self) -> Option<Explain<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe {
            self._tab
                .get::<flatbuffers::ForwardsUOffset<Explain>>(Query::VT_EXPLAIN, None)
        }
    }
}

impl flatbuffers::Verifiable for Query<'_> {
    #[inline]
    fn run_verifier(
        v: &mut flatbuffers::Verifier,
        pos: usize,
    ) -> Result<(), flatbuffers::InvalidFlatbuffer> {
        use self::flatbuffers::Verifiable;
        v.visit_table(pos)?
            .visit_field::<flatbuffers::ForwardsUOffset<QueryElement>>(
                "query",
                Self::VT_QUERY,
                true,
            )?
            .visit_field::<flatbuffers::ForwardsUOffset<
                flatbuffers::Vector<'_, flatbuffers::ForwardsUOffset<ValueInstance>>,
            >>("values", Self::VT_VALUES, false)?
            .visit_field::<u32>("limit", Self::VT_LIMIT, false)?
            .visit_field::<flatbuffers::ForwardsUOffset<
                flatbuffers::Vector<'_, flatbuffers::ForwardsUOffset<TableSourceInstance>>,
            >>("bound_sources", Self::VT_BOUND_SOURCES, false)?
            .visit_field::<flatbuffers::ForwardsUOffset<Explain>>(
                "explain",
                Self::VT_EXPLAIN,
                false,
            )?
            .finish();
        Ok(())
    }
}
pub struct QueryArgs<'a> {
    pub query: Option<flatbuffers::WIPOffset<QueryElement<'a>>>,
    pub values: Option<
        flatbuffers::WIPOffset<
            flatbuffers::Vector<'a, flatbuffers::ForwardsUOffset<ValueInstance<'a>>>,
        >,
    >,
    pub limit: u32,
    pub bound_sources: Option<
        flatbuffers::WIPOffset<
            flatbuffers::Vector<'a, flatbuffers::ForwardsUOffset<TableSourceInstance<'a>>>,
        >,
    >,
    pub explain: Option<flatbuffers::WIPOffset<Explain<'a>>>,
}
impl<'a> Default for QueryArgs<'a> {
    #[inline]
    fn default() -> Self {
        QueryArgs {
            query: None, // required field
            values: None,
            limit: 0,
            bound_sources: None,
            explain: None,
        }
    }
}

impl Serialize for Query<'_> {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        let mut s = serializer.serialize_struct("Query", 5)?;
        s.serialize_field("query", &self.query())?;
        if let Some(f) = self.values() {
            s.serialize_field("values", &f)?;
        } else {
            s.skip_field("values")?;
        }
        s.serialize_field("limit", &self.limit())?;
        if let Some(f) = self.bound_sources() {
            s.serialize_field("bound_sources", &f)?;
        } else {
            s.skip_field("bound_sources")?;
        }
        if let Some(f) = self.explain() {
            s.serialize_field("explain", &f)?;
        } else {
            s.skip_field("explain")?;
        }
        s.end()
    }
}

pub struct QueryBuilder<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> {
    fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a, A>,
    start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> QueryBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_query(&mut self, query: flatbuffers::WIPOffset<QueryElement<'b>>) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<QueryElement>>(Query::VT_QUERY, query);
    }
    #[inline]
    pub fn add_values(
        &mut self,
        values: flatbuffers::WIPOffset<
            flatbuffers::Vector<'b, flatbuffers::ForwardsUOffset<ValueInstance<'b>>>,
        >,
    ) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<_>>(Query::VT_VALUES, values);
    }
    #[inline]
    pub fn add_limit(&mut self, limit: u32) {
        self.fbb_.push_slot::<u32>(Query::VT_LIMIT, limit, 0);
    }
    #[inline]
    pub fn add_bound_sources(
        &mut self,
        bound_sources: flatbuffers::WIPOffset<
            flatbuffers::Vector<'b, flatbuffers::ForwardsUOffset<TableSourceInstance<'b>>>,
        >,
    ) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<_>>(Query::VT_BOUND_SOURCES, bound_sources);
    }
    #[inline]
    pub fn add_explain(&mut self, explain: flatbuffers::WIPOffset<Explain<'b>>) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<Explain>>(Query::VT_EXPLAIN, explain);
    }
    #[inline]
    pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>) -> QueryBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        QueryBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }
    #[inline]
    pub fn finish(self) -> flatbuffers::WIPOffset<Query<'a>> {
        let o = self.fbb_.end_table(self.start_);
        self.fbb_.required(o, Query::VT_QUERY, "query");
        flatbuffers::WIPOffset::new(o.value())
    }
}

impl core::fmt::Debug for Query<'_> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut ds = f.debug_struct("Query");
        ds.field("query", &self.query());
        ds.field("values", &self.values());
        ds.field("limit", &self.limit());
        ds.field("bound_sources", &self.bound_sources());
        ds.field("explain", &self.explain());
        ds.finish()
    }
}
